import React, { useState, useEffect } from 'react';
import { toast } from 'react-toastify';
import { FiPlus, FiEdit2, FiTrash2, FiPlay } from 'react-icons/fi';
import api from '../../services/api';
import AdminTable from '../common/AdminTable';
import AdminModal from '../common/AdminModal';
import AdminCard from '../common/AdminCard';

const AdminVideos = () => {
  const [videos, setVideos] = useState([]);
  const [loading, setLoading] = useState(true);
  const [modalOpen, setModalOpen] = useState(false);
  const [editingVideo, setEditingVideo] = useState(null);
  const [formData, setFormData] = useState({
    title: '',
    description: '',
    video_url: '',
    thumbnail: '',
    category: '',
    date: '',
    is_featured: false,
  });

  const categories = ['School Activities', 'Classroom', 'Graduation', 'Trips', 'Special Events'];

  useEffect(() => {
    fetchVideos();
  }, []);

  const fetchVideos = async () => {
    try {
      const response = await api.get('/api/videos/');
      setVideos(response.data);
    } catch (error) {
      toast.error('Failed to load videos');
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      if (editingVideo) {
        await api.put(`/api/videos/${editingVideo.id}`, formData);
        toast.success('Video updated successfully');
      } else {
        await api.post('/api/videos/', formData);
        toast.success('Video added successfully');
      }
      setModalOpen(false);
      setEditingVideo(null);
      setFormData({
        title: '',
        description: '',
        video_url: '',
        thumbnail: '',
        category: '',
        date: '',
        is_featured: false,
      });
      fetchVideos();
    } catch (error) {
      toast.error(error.response?.data?.detail || 'Operation failed');
    }
  };

  const handleDelete = async (id) => {
    if (window.confirm('Are you sure you want to delete this video?')) {
      try {
        await api.delete(`/api/videos/${id}`);
        toast.success('Video deleted successfully');
        fetchVideos();
      } catch (error) {
        toast.error('Failed to delete video');
      }
    }
  };

  const handleEdit = (video) => {
    setEditingVideo(video);
    setFormData({
      title: video.title,
      description: video.description || '',
      video_url: video.video_url,
      thumbnail: video.thumbnail || '',
      category: video.category || '',
      date: video.date.slice(0, 16),
      is_featured: video.is_featured,
    });
    setModalOpen(true);
  };

  const columns = [
    { key: 'title', label: 'Title' },
    {
      key: 'thumbnail',
      label: 'Thumbnail',
      render: (val) => (
        <img src={val || 'https://via.placeholder.com/100x60'} alt="Thumbnail" className="w-24 h-14 object-cover rounded" />
      ),
    },
    { key: 'category', label: 'Category' },
    {
      key: 'date',
      label: 'Date',
      render: (val) => new Date(val).toLocaleDateString(),
    },
    { key: 'views', label: 'Views' },
    {
      key: 'actions',
      label: 'Actions',
      render: (_, row) => (
        <div className="flex space-x-2">
          <button
            onClick={() => handleEdit(row)}
            className="text-blue-600 hover:text-blue-800"
          >
            <FiEdit2 />
          </button>
          <button
            onClick={() => handleDelete(row.id)}
            className="text-red-600 hover:text-red-800"
          >
            <FiTrash2 />
          </button>
        </div>
      ),
    },
  ];

  return (
    <div>
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-3xl font-bold text-blue-900">Videos Management</h1>
        <button
          onClick={() => {
            setEditingVideo(null);
            setFormData({
              title: '',
              description: '',
              video_url: '',
              thumbnail: '',
              category: '',
              date: '',
              is_featured: false,
            });
            setModalOpen(true);
          }}
          className="admin-btn-primary flex items-center space-x-2"
        >
          <FiPlus />
          <span>Add Video</span>
        </button>
      </div>

      <AdminCard>
        <AdminTable
          columns={columns}
          data={videos}
          loading={loading}
        />
      </AdminCard>

      <AdminModal
        isOpen={modalOpen}
        onClose={() => {
          setModalOpen(false);
          setEditingVideo(null);
        }}
        title={editingVideo ? 'Edit Video' : 'Add Video'}
      >
        <form onSubmit={handleSubmit}>
          <div className="space-y-4">
            <div>
              <label className="admin-label">Title *</label>
              <input
                type="text"
                value={formData.title}
                onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                className="admin-input"
                required
              />
            </div>
            <div>
              <label className="admin-label">Description</label>
              <textarea
                value={formData.description}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                className="admin-input"
                rows="3"
              />
            </div>
            <div>
              <label className="admin-label">Video URL (YouTube/Facebook) *</label>
              <input
                type="text"
                value={formData.video_url}
                onChange={(e) => setFormData({ ...formData, video_url: e.target.value })}
                className="admin-input"
                required
                placeholder="https://www.youtube.com/watch?v=..."
              />
            </div>
            <div>
              <label className="admin-label">Thumbnail URL</label>
              <input
                type="text"
                value={formData.thumbnail}
                onChange={(e) => setFormData({ ...formData, thumbnail: e.target.value })}
                className="admin-input"
                placeholder="https://example.com/thumbnail.jpg"
              />
            </div>
            <div>
              <label className="admin-label">Category</label>
              <select
                value={formData.category}
                onChange={(e) => setFormData({ ...formData, category: e.target.value })}
                className="admin-input"
              >
                <option value="">Select Category</option>
                {categories.map((cat) => (
                  <option key={cat} value={cat}>{cat}</option>
                ))}
              </select>
            </div>
            <div>
              <label className="admin-label">Date *</label>
              <input
                type="datetime-local"
                value={formData.date}
                onChange={(e) => setFormData({ ...formData, date: e.target.value })}
                className="admin-input"
                required
              />
            </div>
            <div>
              <label className="flex items-center space-x-2">
                <input
                  type="checkbox"
                  checked={formData.is_featured}
                  onChange={(e) => setFormData({ ...formData, is_featured: e.target.checked })}
                />
                <span>Featured Video</span>
              </label>
            </div>
          </div>
          <div className="mt-6 flex justify-end space-x-3">
            <button
              type="button"
              onClick={() => {
                setModalOpen(false);
                setEditingVideo(null);
              }}
              className="admin-btn-secondary"
            >
              Cancel
            </button>
            <button type="submit" className="admin-btn-primary">
              {editingVideo ? 'Update' : 'Add'}
            </button>
          </div>
        </form>
      </AdminModal>
    </div>
  );
};

export default AdminVideos;
